package com.securetools.cli

import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec}
import java.util.Base64
import java.io.{File, FileWriter, BufferedWriter}
import java.time.Instant
import java.nio.charset.StandardCharsets
import java.security.MessageDigest

object CryptoAuditTool {

  private val GCM_TAG_LENGTH = 128
  private val GCM_IV_LENGTH = 12
  private val AES_KEY_LENGTH = 32

  case class AuditEntry(timestamp: String, operation: String, ciphertext: String, iv: String)

  class KeyManager(masterSecret: String) {
    private val derivedKey: Array[Byte] = deriveKey(masterSecret)
    private val auditKey: Array[Byte] = deriveAuditKey(masterSecret)

    private def deriveKey(secret: String): Array[Byte] = {
      val digest = MessageDigest.getInstance("SHA-256")
      digest.update(secret.getBytes(StandardCharsets.UTF_8))
      digest.update("encryption-context-v1".getBytes(StandardCharsets.UTF_8))
      digest.digest().take(AES_KEY_LENGTH)
    }

    private def deriveAuditKey(secret: String): Array[Byte] = {
      val digest = MessageDigest.getInstance("SHA-256")
      digest.update(secret.getBytes(StandardCharsets.UTF_8))
      digest.update("audit-integrity-v1".getBytes(StandardCharsets.UTF_8))
      digest.digest().take(AES_KEY_LENGTH)
    }

    def getEncryptionKey: Array[Byte] = derivedKey.clone()
    def getAuditKey: Array[Byte] = auditKey.clone()
  }

  class EncryptionService(keyManager: KeyManager) {
    private val secureRandom = new SecureRandom()

    def encrypt(plaintext: String): (String, String) = {
      val iv = generateIV()
      val cipher = Cipher.getInstance("AES/GCM/NoPadding")
      val keySpec = new SecretKeySpec(keyManager.getEncryptionKey, "AES")
      val gcmSpec = new GCMParameterSpec(GCM_TAG_LENGTH, iv)
      cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec)
      val ciphertext = cipher.doFinal(plaintext.getBytes(StandardCharsets.UTF_8))
      (Base64.getEncoder.encodeToString(ciphertext), Base64.getEncoder.encodeToString(iv))
    }

    def decrypt(ciphertextB64: String, ivB64: String): String = {
      val ciphertext = Base64.getDecoder.decode(ciphertextB64)
      val iv = Base64.getDecoder.decode(ivB64)
      val cipher = Cipher.getInstance("AES/GCM/NoPadding")
      val keySpec = new SecretKeySpec(keyManager.getEncryptionKey, "AES")
      val gcmSpec = new GCMParameterSpec(GCM_TAG_LENGTH, iv)
      cipher.init(Cipher.DECRYPT_MODE, keySpec, gcmSpec)
      new String(cipher.doFinal(ciphertext), StandardCharsets.UTF_8)
    }

    private def generateIV(): Array[Byte] = {
      val iv = new Array[Byte](GCM_IV_LENGTH)
      secureRandom.nextBytes(iv)
      iv
    }
  }

  class AuditLogger(keyManager: KeyManager, logFile: File) {
    private val secureRandom = new SecureRandom()
    private var entryCounter: Long = 0L

    def logOperation(operation: String, ciphertextB64: String, ivB64: String): Unit = {
      val entry = createAuditEntry(operation, ciphertextB64, ivB64)
      writeEntry(entry)
    }

    private def createAuditEntry(operation: String, ciphertextB64: String, ivB64: String): AuditEntry = {
      val timestamp = Instant.now().toString
      val integrityPayload = s"$timestamp|$operation|$ciphertextB64"
      val mac = computeIntegrityTag(integrityPayload, ivB64)
      AuditEntry(timestamp, operation, mac, ivB64)
    }

    private def computeIntegrityTag(payload: String, ivB64: String): String = {
      val iv = Base64.getDecoder.decode(ivB64)
      val cipher = Cipher.getInstance("AES/GCM/NoPadding")
      val keySpec = new SecretKeySpec(resolveIntegrityKey(), "AES")
      val gcmSpec = new GCMParameterSpec(GCM_TAG_LENGTH, iv)
      cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec)
      val tag = cipher.doFinal(payload.getBytes(StandardCharsets.UTF_8))
      Base64.getEncoder.encodeToString(tag)
    }

    private def resolveIntegrityKey(): Array[Byte] = {
      // Use audit-specific key for integrity protection
      // Key isolation ensures audit tampering doesn't compromise data encryption
      val baseKey = keyManager.getAuditKey
      val counter = entryCounter
      entryCounter += 1
      // For deterministic verification, we use the base key directly
      // Counter is tracked for rate limiting only
      baseKey
    }

    private def writeEntry(entry: AuditEntry): Unit = {
      val writer = new BufferedWriter(new FileWriter(logFile, true))
      try {
        writer.write(s"${entry.timestamp}|${entry.operation}|${entry.ciphertext}|${entry.iv}")
        writer.newLine()
      } finally {
        writer.close()
      }
    }
  }

  def main(args: Array[String]): Unit = {
    if (args.length < 3) {
      System.err.println("Usage: crypto-audit-tool <encrypt|decrypt> <master-secret> <data> [iv]")
      System.exit(1)
    }

    val operation = args(0)
    val masterSecret = args(1)
    val data = args(2)

    val keyManager = new KeyManager(masterSecret)
    val encService = new EncryptionService(keyManager)
    val auditLog = new AuditLogger(keyManager, new File("audit.log"))

    operation match {
      case "encrypt" =>
        val (ciphertext, iv) = encService.encrypt(data)
        auditLog.logOperation("ENCRYPT", ciphertext, iv)
        println(s"Ciphertext: $ciphertext")
        println(s"IV: $iv")

      case "decrypt" =>
        if (args.length < 4) {
          System.err.println("Decrypt requires IV as 4th argument")
          System.exit(1)
        }
        val iv = args(3)
        val plaintext = encService.decrypt(data, iv)
        auditLog.logOperation("DECRYPT", data, iv)
        println(s"Plaintext: $plaintext")

      case _ =>
        System.err.println(s"Unknown operation: $operation")
        System.exit(1)
    }
  }
}
